import React, { useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Container,
  Link,
  Paper,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import { Link as RouterLink } from 'react-router-dom';
import { buildApiUrl } from '../../config/apiConfig';
import BrandLockup from '../BrandLockup';
import {
  PARTNER_CONTACT_EMAIL,
  PARTNER_PROGRAM_SUMMARY,
  PARTNER_SUPPORT_EMAIL,
} from '../../constants/partnerProgram';

interface IntegrationCatalog {
  version: string;
  authentication: {
    type: string;
    headerOptions: string[];
    keyPrefix: string;
    note: string;
  };
  scopes: { id: string; description: string }[];
  endpoints: { method: string; path: string; access: string; scopes?: string[] }[];
  supportEmail: string;
}

const PartnersPage: React.FC = () => {
  const [catalog, setCatalog] = useState<IntegrationCatalog | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetch(buildApiUrl('/v1/public/integration-catalog'))
      .then(async (res) => {
        const body = await res.json();
        if (!res.ok || !body.success) {
          throw new Error(body.message || 'Failed to load integration catalog');
        }
        setCatalog(body.data);
      })
      .catch((err: Error) => setError(err.message));
  }, []);

  const openapiUrl = buildApiUrl('/v1/public/openapi.json');
  const supportEmail = catalog?.supportEmail || PARTNER_SUPPORT_EMAIL;

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: 'background.default', py: 4 }}>
      <Container maxWidth="lg">
        <Stack spacing={3}>
          <BrandLockup width={220} />
          <Box>
            <Typography variant="h4" component="h1" gutterBottom>
              Partners
            </Typography>
            <Typography variant="body1" color="text.secondary" sx={{ maxWidth: 800 }}>
              {PARTNER_PROGRAM_SUMMARY}
            </Typography>
          </Box>

          <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
            <Button variant="contained" component={RouterLink} to="/login">
              Partner portal sign in
            </Button>
            <Button variant="outlined" href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20enquiry`}>
              Request partnership proposal
            </Button>
            <Button variant="outlined" component={RouterLink} to="/pricing">
              MSME pricing
            </Button>
            <Button variant="text" href={openapiUrl} target="_blank" rel="noopener noreferrer">
              OpenAPI JSON
            </Button>
          </Stack>

          <Alert severity="info">
            Partnership and API usage pricing is shared on request. For commercial terms, email{' '}
            <Link href={`mailto:${PARTNER_CONTACT_EMAIL}?subject=Partnership%20pricing%20enquiry`}>
              {PARTNER_CONTACT_EMAIL}
            </Link>
            .
          </Alert>

          <Paper
            id="public-api-documentation"
            sx={{ p: 3, scrollMarginTop: { xs: 96, md: 120 } }}
          >
            <Stack spacing={2}>
              <Box>
                <Typography variant="h5" gutterBottom>
                  Public API documentation
                </Typography>
                <Typography variant="body2" color="text.secondary" paragraph>
                  Reference the public partner API catalog and OpenAPI document for scoped REST integrations,
                  authentication headers, usage metering, and webhook configuration.
                </Typography>
                <Button variant="text" href={openapiUrl} target="_blank" rel="noopener noreferrer" sx={{ px: 0 }}>
                  OpenAPI JSON
                </Button>
              </Box>

              {catalog ? (
                <>
                  <Box>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      Version <strong>{catalog.version}</strong> — authenticate with partner API keys (
                      <code>{catalog.authentication.keyPrefix}</code>).
                    </Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      {catalog.authentication.note}
                    </Typography>
                    <Stack direction="row" spacing={1} flexWrap="wrap" useFlexGap>
                      {catalog.authentication.headerOptions.map((header) => (
                        <Chip key={header} label={header} size="small" variant="outlined" />
                      ))}
                    </Stack>
                  </Box>

                  <Box>
                    <Typography variant="h6" sx={{ mb: 1 }}>
                      Scopes
                    </Typography>
                    <TableContainer sx={{ mb: 3 }}>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Scope</TableCell>
                            <TableCell>Description</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {catalog.scopes.map((scope) => (
                            <TableRow key={scope.id}>
                              <TableCell>
                                <code>{scope.id}</code>
                              </TableCell>
                              <TableCell>{scope.description}</TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>

                    <Typography variant="h6" sx={{ mb: 1 }}>
                      Endpoints
                    </Typography>
                    <TableContainer>
                      <Table size="small">
                        <TableHead>
                          <TableRow>
                            <TableCell>Method</TableCell>
                            <TableCell>Path</TableCell>
                            <TableCell>Access</TableCell>
                            <TableCell>Scopes</TableCell>
                          </TableRow>
                        </TableHead>
                        <TableBody>
                          {catalog.endpoints.map((endpoint) => (
                            <TableRow key={`${endpoint.method}-${endpoint.path}`}>
                              <TableCell>{endpoint.method}</TableCell>
                              <TableCell>
                                <code>{endpoint.path}</code>
                              </TableCell>
                              <TableCell>{endpoint.access}</TableCell>
                              <TableCell>
                                {endpoint.scopes?.length ? endpoint.scopes.join(', ') : '—'}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </TableContainer>
                  </Box>
                </>
              ) : (
                <Alert severity={error ? 'warning' : 'info'}>
                  {error
                    ? `Could not load the integration catalog: ${error}. You can still open the public OpenAPI JSON document.`
                    : 'Loading public API catalog...'}
                </Alert>
              )}
            </Stack>
          </Paper>

          <Alert severity="info">
            Production API keys are issued by Carbon Intelligence administrators. If you already have reviewer
            access, open the{' '}
            <Link component={RouterLink} to="/admin/integrations">
              integrations portal
            </Link>
            . For technical support, email{' '}
            <Link href={`mailto:${supportEmail}`}>{supportEmail}</Link>.
          </Alert>
        </Stack>
      </Container>
    </Box>
  );
};

export default PartnersPage;
