export type ReadinessLevel = 'aligned' | 'ready' | 'configured' | 'active' | 'connected' | 'data_available' | 'template_ready' | 'datapoints_available' | 'products_registered' | 'applicable' | 'in_progress' | 'needs_improvement' | 'review_required' | 'needs_products' | 'needs_inventory' | 'needs_activity_data' | 'import_only' | 'empty' | 'not_applicable' | 'not_started';

const READINESS_LABELS: Record<ReadinessLevel, string> = {
  aligned: 'Aligned',
  ready: 'Ready',
  configured: 'Configured',
  active: 'Active',
  connected: 'Connected',
  data_available: 'Data available',
  template_ready: 'Template ready',
  datapoints_available: 'Datapoints available',
  products_registered: 'Products registered',
  applicable: 'Applicable',
  in_progress: 'In progress',
  needs_improvement: 'Needs improvement',
  review_required: 'Review required',
  needs_products: 'Needs products',
  needs_inventory: 'Needs inventory',
  needs_activity_data: 'Needs activity data',
  import_only: 'Import only',
  empty: 'Empty',
  not_applicable: 'Not applicable',
  not_started: 'Not started',
};

const isComplianceHubPayload = (value: Record<string, unknown>): boolean =>
  'readiness' in value
  || 'indiaReadiness' in value
  || 'exportReadiness' in value
  || 'modules' in value
  || 'exportProfile' in value;

/** Unwrap compliance-hub API payloads whether nested under `data` or returned flat. */
export const unwrapComplianceHubPayload = <T extends Record<string, unknown>>(
  response: unknown
): T | null => {
  if (!response || typeof response !== 'object') {
    return null;
  }
  let body = response as Record<string, unknown>;
  for (let depth = 0; depth < 3; depth += 1) {
    if (isComplianceHubPayload(body)) {
      return body as T;
    }
    if (body.data && typeof body.data === 'object') {
      body = body.data as Record<string, unknown>;
      continue;
    }
    break;
  }
  return isComplianceHubPayload(body) ? (body as T) : null;
};

const normalizeStatusKey = (level?: string): string | undefined => {
  const trimmed = level?.trim();
  if (!trimmed) {
    return undefined;
  }
  return trimmed.toLowerCase();
};

