export const readinessChipColor = (
  level?: string
): 'success' | 'warning' | 'error' | 'default' | 'info' => {
  if (!level) return 'default';
  if (
    ['aligned', 'ready', 'configured', 'active', 'connected', 'data_available', 'template_ready', 'datapoints_available', 'products_registered', 'applicable'].includes(level)
  ) {
    return 'success';
  }
  if (['in_progress', 'review_required', 'import_only', 'empty'].includes(level)) {
    return 'warning';
  }
  if (['needs_improvement', 'needs_products', 'needs_inventory', 'needs_activity_data', 'not_started'].includes(level)) {
    return 'error';
  }
  if (level === 'not_applicable') return 'default';
  return 'info';
};

export const readinessLabel = (level?: string): string => {
  const normalized = normalizeStatusKey(level);
  if (!normalized || normalized === 'unknown') {
    return 'Not started';
  }
  const mapped = READINESS_LABELS[normalized as ReadinessLevel];
  if (mapped) {
    return mapped;
  }
  return normalized.replace(/_/g, ' ');
};

/** Human-readable labels for workflow rows (questionnaires, action plans). */
export const complianceWorkflowStatusLabel = (status?: string): string => {
  const normalized = normalizeStatusKey(status);
  if (!normalized || normalized === 'unknown') {
    return 'Not started';
  }
  const workflowLabels: Record<string, string> = {
    draft: 'Draft',
    sent: 'Sent',
    responded: 'Responded',
    accepted: 'Accepted',
    revision_requested: 'Revision requested',
    planned: 'Planned',
    in_progress: 'In progress',
    completed: 'Completed',
    deferred: 'Deferred',
  };
  return workflowLabels[normalized] ?? readinessLabel(status);
};
