import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  FormControl,
  Grid,
  InputLabel,
  LinearProgress,
  MenuItem,
  Select,
  Stack,
  TextField,
  Typography,
  Link as MuiLink,
  Stepper,
  Step,
  StepLabel
} from '@mui/material';
import {
  Bolt as BoltIcon,
  CheckCircle as CheckCircleIcon,
  Cancel as CancelIcon,
  OpenInNew as OpenInNewIcon,
  Savings as SavingsIcon
} from '@mui/icons-material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import api from '../services/api';

interface AdeetieCriterion {
  id: string;
  label: string;
  passed: boolean;
  hint?: string | null;
  current?: unknown;
}

interface AdeetieOverview {
  scheme: {
    schemeName: string;
    links: { portal: string; pib: string };
    subventionRates: Record<string, number>;
    loanBand: { minInr: number; maxInr: number };
  };
  eligibility: {
    isEligible: boolean;
    subventionRatePercent: number | null;
    criteria: AdeetieCriterion[];
    links: { portal: string; pib: string };
    beeSector?: string;
    cluster?: { id: string; name: string; state: string; sectorId: string } | null;
  };
  readiness: {
    readinessScore: number;
    estimatedEnergySavingsPercent: number;
    minRequiredSavingsPercent: number;
    gapToTargetPercent: number;
    energyRecommendations: Array<{ id: string; title: string; status: string }>;
  };
  journey: { stage: string; updatedAt?: string };
}

const JOURNEY_LABELS: Record<string, string> = {
  not_started: 'Not started',
  eligibility_reviewed: 'Eligibility reviewed',
  expression_of_interest: 'Expression of interest',
  igea_scheduled: 'IGEA scheduled',
  dpr_prepared: 'DPR prepared',
  loan_sanctioned: 'Loan sanctioned',
  implementation: 'Implementation',
  monitoring_verification: 'M&V',
  subvention_claimed: 'Subvention claimed'
};

const formatInr = (value: number) =>
  new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(value);

const ADEETIEHub: React.FC = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [overview, setOverview] = useState<AdeetieOverview | null>(null);
  const [sectors, setSectors] = useState<Array<{ id: string; label: string }>>([]);
  const [clusters, setClusters] = useState<Array<{ id: string; name: string; state: string; sectorId: string }>>([]);
  const [beeSector, setBeeSector] = useState('');
  const [adeetieClusterId, setAdeetieClusterId] = useState('');
  const [loanAmount, setLoanAmount] = useState('5000000');
  const [nominalRate, setNominalRate] = useState('12');
  const [subventionResult, setSubventionResult] = useState<Record<string, unknown> | null>(null);
  const [savingProfile, setSavingProfile] = useState(false);
  const [exportingDpr, setExportingDpr] = useState(false);

  const loadOverview = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [overviewRes, clustersRes] = await Promise.all([
        api.getAdeetieOverview(),
        api.getAdeetieClusters()
      ]);
      const data = overviewRes?.data as AdeetieOverview;
      setOverview(data);
      setSectors(clustersRes?.data?.sectors || []);
      setClusters(clustersRes?.data?.clusters || []);
      setBeeSector(data?.eligibility?.beeSector || '');
      setAdeetieClusterId(data?.eligibility?.cluster?.id || '');
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to load ADEETIE data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadOverview();
  }, [loadOverview]);

  const filteredClusters = beeSector
    ? clusters.filter((c) => c.sectorId === beeSector)
    : clusters;

  const handleSaveProfile = async () => {
    setSavingProfile(true);
    try {
      await api.updateAdeetieProfile({ beeSector, adeetieClusterId });
      await loadOverview();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to update profile');
    } finally {
      setSavingProfile(false);
    }
  };

  const handleCalculateSubvention = async () => {
    try {
      const res = await api.calculateAdeetieSubvention({
        loanAmount: Number(loanAmount),
        nominalInterestRatePercent: Number(nominalRate),
        tenureYears: 3
      });
      setSubventionResult(res?.data as Record<string, unknown>);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Subvention calculation failed');
    }
  };

  const handleExportDpr = async () => {
    setExportingDpr(true);
    try {
      const res = await api.getAdeetieDprBrief();
      const blob = new Blob([JSON.stringify(res?.data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = 'adeetie-dpr-brief.json';
      anchor.click();
      URL.revokeObjectURL(url);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'DPR export failed');
    } finally {
      setExportingDpr(false);
    }
  };

  const handleJourneyAdvance = async (stage: string) => {
    try {
      await api.updateAdeetieJourney({ stage });
      await loadOverview();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to update journey');
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight={320}>
        <CircularProgress />
      </Box>
    );
  }

  if (!overview) {
    return <Alert severity="error">{error || 'Unable to load ADEETIE programme data.'}</Alert>;
  }

  const { scheme, eligibility, readiness, journey } = overview;
  const subvention = subventionResult?.subvention as Record<string, number> | undefined;

  return (
    <Box sx={{ p: { xs: 2, md: 3 }, maxWidth: 1200, mx: 'auto' }}>
      <Stack direction="row" alignItems="center" spacing={1} mb={1}>
        <BoltIcon color="primary" />
        <Typography variant="h4" component="h1">
          ADEETIE Programme
        </Typography>
      </Stack>
      <Typography variant="body1" color="text.secondary" paragraph>
        {scheme.schemeName} — interest subvention and technical handholding from BEE for MSME energy-efficiency
        projects (FY 2025–26 to 2027–28).
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      <Grid container spacing={3}>
        <Grid item xs={12} md={8}>
          <Card variant="outlined" sx={{ mb: 3 }}>
            <CardContent>
              <Stack direction="row" justifyContent="space-between" alignItems="center" mb={2}>
                <Typography variant="h6">Eligibility</Typography>
                <Chip
                  icon={eligibility.isEligible ? <CheckCircleIcon /> : <CancelIcon />}
                  label={eligibility.isEligible ? 'Eligible' : 'Action needed'}
                  color={eligibility.isEligible ? 'success' : 'warning'}
                />
              </Stack>
              <Stack spacing={1}>
                {eligibility.criteria.map((c) => (
                  <Stack key={c.id} direction="row" spacing={1} alignItems="flex-start">
                    {c.passed ? (
                      <CheckCircleIcon color="success" fontSize="small" />
                    ) : (
                      <CancelIcon color="error" fontSize="small" />
                    )}
                    <Box>
                      <Typography variant="body2">{c.label}</Typography>
                      {!c.passed && c.hint && (
                        <Typography variant="caption" color="text.secondary">
                          {c.hint}
                        </Typography>
                      )}
                    </Box>
                  </Stack>
                ))}
              </Stack>
              <Stack direction="row" spacing={2} mt={2} flexWrap="wrap">
                <Button
                  variant="outlined"
                  href={eligibility.links.portal}
                  target="_blank"
                  rel="noopener noreferrer"
                  endIcon={<OpenInNewIcon />}
                >
                  BEE ADEETIE portal
                </Button>
                <Button
                  variant="text"
                  href={eligibility.links.pib}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  PIB launch note
                </Button>
              </Stack>
            </CardContent>
          </Card>

          <Card variant="outlined" sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Readiness score
              </Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 1 }}>
                <LinearProgress
                  variant="determinate"
                  value={readiness.readinessScore}
                  sx={{ flex: 1, height: 10, borderRadius: 1 }}
                />
                <Typography variant="h6">{readiness.readinessScore}%</Typography>
              </Box>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Estimated energy savings: {readiness.estimatedEnergySavingsPercent}% (target{' '}
                {readiness.minRequiredSavingsPercent}% for annual subvention)
              </Typography>
              {readiness.gapToTargetPercent > 0 && (
                <Alert severity="info" sx={{ mt: 1 }}>
                  Implement energy measures to close a {readiness.gapToTargetPercent}% gap to the ADEETIE savings
                  threshold.
                </Alert>
              )}
              {readiness.energyRecommendations.length > 0 && (
                <Box mt={2}>
                  <Typography variant="subtitle2" gutterBottom>
                    Energy recommendations
                  </Typography>
                  {readiness.energyRecommendations.map((r) => (
                    <Typography key={r.id} variant="body2">
                      • {r.title} ({r.status})
                    </Typography>
                  ))}
                  <Button
                    size="small"
                    sx={{ mt: 1 }}
                    component={RouterLink}
                    to="/carbon-footprint?section=recommendations"
                  >
                    View all recommendations
                  </Button>
                </Box>
              )}
            </CardContent>
          </Card>

          <Card variant="outlined">
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Application journey
              </Typography>
              <Stepper activeStep={Math.max(0, Object.keys(JOURNEY_LABELS).indexOf(journey.stage))} alternativeLabel sx={{ mb: 2 }}>
                {Object.entries(JOURNEY_LABELS).slice(0, 5).map(([key, label]) => (
                  <Step key={key}>
                    <StepLabel>{label}</StepLabel>
                  </Step>
                ))}
              </Stepper>
              <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                <InputLabel>Current stage</InputLabel>
                <Select
                  value={journey.stage}
                  label="Current stage"
                  onChange={(e) => handleJourneyAdvance(e.target.value)}
                >
                  {Object.entries(JOURNEY_LABELS).map(([key, label]) => (
                    <MenuItem key={key} value={key}>
                      {label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <Button variant="outlined" onClick={handleExportDpr} disabled={exportingDpr}>
                {exportingDpr ? 'Preparing…' : 'Download DPR evidence brief (JSON)'}
              </Button>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} md={4}>
          <Card variant="outlined" sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Your ADEETIE profile
              </Typography>
              <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                <InputLabel>BEE sector</InputLabel>
                <Select
                  value={beeSector}
                  label="BEE sector"
                  onChange={(e) => {
                    setBeeSector(e.target.value);
                    setAdeetieClusterId('');
                  }}
                >
                  {sectors.map((s) => (
                    <MenuItem key={s.id} value={s.id}>
                      {s.label}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <FormControl fullWidth size="small" sx={{ mb: 2 }}>
                <InputLabel>Phase-1 cluster</InputLabel>
                <Select
                  value={adeetieClusterId}
                  label="Phase-1 cluster"
                  onChange={(e) => setAdeetieClusterId(e.target.value)}
                >
                  {filteredClusters.map((c) => (
                    <MenuItem key={c.id} value={c.id}>
                      {c.name} ({c.state})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <Button variant="contained" fullWidth onClick={handleSaveProfile} disabled={savingProfile}>
                {savingProfile ? 'Saving…' : 'Save profile'}
              </Button>
            </CardContent>
          </Card>

          <Card variant="outlined" sx={{ mb: 3 }}>
            <CardContent>
              <Stack direction="row" alignItems="center" spacing={1} mb={1}>
                <SavingsIcon color="primary" />
                <Typography variant="h6">Subvention calculator</Typography>
              </Stack>
              <Typography variant="caption" color="text.secondary" display="block" mb={2}>
                {eligibility.subventionRatePercent}% p.a. for your enterprise size on eligible loans.
              </Typography>
              <TextField
                fullWidth
                size="small"
                label="Loan amount (INR)"
                type="number"
                value={loanAmount}
                onChange={(e) => setLoanAmount(e.target.value)}
                sx={{ mb: 2 }}
              />
              <TextField
                fullWidth
                size="small"
                label="Nominal interest rate (%)"
                type="number"
                value={nominalRate}
                onChange={(e) => setNominalRate(e.target.value)}
                sx={{ mb: 2 }}
              />
              <Button variant="contained" fullWidth onClick={handleCalculateSubvention}>
                Calculate savings
              </Button>
              {subvention && (
                <Box mt={2}>
                  <Typography variant="body2">
                    Effective rate: <strong>{subvention.effectiveInterestRatePercent}%</strong>
                  </Typography>
                  <Typography variant="body2">
                    Total subvention ({subvention.tenureYears} yr):{' '}
                    <strong>{formatInr(subvention.totalSubventionInr)}</strong>
                  </Typography>
                </Box>
              )}
              <Button
                fullWidth
                sx={{ mt: 2 }}
                variant="outlined"
                onClick={() => navigate('/green-loans')}
              >
                Apply via green loans
              </Button>
            </CardContent>
          </Card>

          <Card variant="outlined">
            <CardContent>
              <Typography variant="subtitle2" gutterBottom>
                Also explore
              </Typography>
              <MuiLink component={RouterLink} to="/gift-schemes" display="block" variant="body2">
                GIFT schemes catalogue
              </MuiLink>
              <MuiLink component={RouterLink} to="/msme-profile" display="block" variant="body2">
                Update company profile
              </MuiLink>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default ADEETIEHub;
